  "170": { mr: "1️⃣ पहिला कलिमा — तैय्यिबा", ar: "1️⃣ الكلمة الأولى — الطيبة", fr: "1️⃣ Première Kalima — Tayyiba", es: "1️⃣ Primera Kalima: Tayyiba" },
  "171": { mr: "2️⃣ दुसरा कलिमा — शहादत", ar: "2️⃣ الكلمة الثانية — الشهادة", fr: "2️⃣ Deuxième Kalima — Shahâda", es: "2️⃣ Segunda Kalima: Shahada" },
