  /* ── ahmiyat ── */
  "256": { mr: "<span class=\"ic\">🌟</span>नमाज़चे महत्त्व", ar: "<span class=\"ic\">🌟</span>أهمية الصلاة", fr: "<span class=\"ic\">🌟</span>L'importance de la prière", es: "<span class=\"ic\">🌟</span>La importancia de la oración" },
  "257": { mr: "निःसंशय नमाज़ मोमिनांवर ठरलेल्या वेळांमध्ये फर्ज आहे.",
           ar: "إن الصلاة كانت على المؤمنين كتابًا موقوتًا.",
           fr: "La prière est pour les croyants une prescription à des heures déterminées.",
           es: "La oración es para los creyentes una obligación en horas determinadas." },
  "258": { mr: "निःसंशय नमाज़ अश्लीलता आणि वाईट कर्मांपासून रोखते.",
           ar: "إن الصلاة تنهى عن الفحشاء والمنكر.",
           fr: "La prière détourne de la turpitude et du blâmable.",
           es: "La oración aparta de la indecencia y de lo reprobable." },
  "259": { mr: "कयामतच्या दिवशी बंद्याकडून सर्वप्रथम त्याच्या नमाज़चा हिशोब घेतला जाईल; जर ती योग्य निघाली तर उर्वरित कर्मेही योग्य ठरतील.",
           ar: "أول ما يحاسب عليه العبد يوم القيامة صلاته؛ فإن صلحت صلح سائر عمله.",
           fr: "Au Jour de la Résurrection, le serviteur est d'abord interrogé sur sa prière : si elle est correcte, le reste de ses œuvres le sera aussi.",
           es: "En el Día del Juicio, lo primero por lo que se pedirá cuentas al siervo es su oración: si es correcta, el resto de sus obras también lo será." },
  "260": { mr: "📖 नबवी हदीस ﷺ (बुरैदा र.अ.)", ar: "📖 حديث النبي ﷺ (بريدة رضي الله عنه)", fr: "📖 Hadith du Prophète ﷺ (Bourayda, qu'Allah l'agrée)", es: "📖 Hadiz del Profeta ﷺ (Burayda, que Alá esté complacido con él)" },
  "261": { mr: "आमच्या आणि त्यांच्या (काफिर/मुनाफिक) दरम्यानचा करार नमाज़ आहे; ज्याने नमाज़ सोडली त्याने कुफ्र केले.",
           ar: "العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر.",
           fr: "Le pacte qui nous lie à eux, c'est la prière : celui qui l'abandonne a mécru.",
           es: "El pacto entre nosotros y ellos es la oración: quien la abandona ha caído en la incredulidad." },
  "262": { mr: "बंदा आणि शिर्क-कुफ्र यांच्यामधील अंतर नमाज़ सोडणे आहे.",
           ar: "بين العبد والشرك والكفر ترك الصلاة.",
           fr: "Entre le serviteur, le polythéisme et la mécréance, il y a l'abandon de la prière.",
           es: "Entre el siervo y el politeísmo y la incredulidad está el abandono de la oración." },
  "263": { mr: "⚖️ <b>जाणूनबुजून नमाज़ सोडणाऱ्याचा हुकूम:</b> नमाज़ची फर्जियत नाकारणारा सर्वांच्या एकमताने इस्लामच्या वर्तुळातून बाहेर आहे. जो आळशीपणाने सोडतो, त्याच्या हुकुमात विद्वानांत मतभेद आहे: एक मत (इमाम अहमद यांची प्रसिद्ध रिवायत, इसहाक बिन राहवैह, इब्नुल-मुबारक, आणि सौदी विद्वान इब्न बाज़ व इब्न उसैमीन) नुसार तो काफिर आहे, कारण हदीसमध्ये नमाज़ सोडण्यावर «कुफ्र» आले आहे आणि सहाबा नमाज़ेशिवाय कोणत्याही कर्माच्या त्यागाला कुफ्र मानत नव्हते (सुनन तिर्मिझी २६२२); दुसरे मत (बहुसंख्य फकीह: हनफी, मालिकी, शाफई) असे आहे की तो कठोर पापी आहे पण काफिर नाही. दोघांच्याही मते नमाज़ सोडणे हा फार मोठा गुन्हा आहे.",
           ar: "⚖️ <b>حكم من ترك الصلاة عمدًا:</b> من أنكر فرضيتها فهو خارج من دائرة الإسلام بالاتفاق. وأما من تركها تهاونًا ففي حكمه خلاف بين أهل العلم: قول (وهو المشهور عن الإمام أحمد، وإسحاق بن راهويه، وابن المبارك، وعلماء السعودية ابن باز وابن عثيمين) أنه كافر، لأن الحديث ورد بلفظ «الكفر» على ترك الصلاة، ولأن الصحابة لم يعدّوا ترك شيء من الأعمال كفرًا إلا الصلاة (سنن الترمذي ٢٦٢٢)؛ وقول آخر (جمهور الفقهاء: الحنفية والمالكية والشافعية) أنه مرتكب لكبيرة عظيمة لكنه ليس بكافر. وعلى القولين فترك الصلاة من أعظم الجرائم.",
           fr: "⚖️ <b>Le statut de celui qui délaisse la prière délibérément :</b> celui qui nie son caractère obligatoire sort de l'islam à l'unanimité. Quant à celui qui la délaisse par paresse, les savants divergent : une opinion (la version connue de l'imam Ahmad, Ishâq ibn Râhawayh, Ibn al-Mubârak et les savants saoudiens Ibn Bâz et Ibn Uthaymîn) le considère comme mécréant, car le hadith emploie le mot « mécréance » pour l'abandon de la prière, et les Compagnons ne considéraient l'abandon d'aucune œuvre comme une mécréance, sauf la prière (Sunan Tirmidhi 2622) ; l'autre opinion (la majorité des juristes : hanafites, malikites, chaféites) est qu'il commet un très grand péché sans être mécréant. Pour les deux, abandonner la prière est un crime immense.",
           es: "⚖️ <b>El dictamen sobre quien abandona la oración deliberadamente:</b> quien niega su obligatoriedad sale del islam por unanimidad. En cuanto a quien la abandona por pereza, los sabios discrepan: una opinión (la conocida del imán Ahmad, Ishaq ibn Rahuya, Ibn al-Mubarak y los sabios saudíes Ibn Baz e Ibn Uzaymin) dice que es incrédulo, porque el hadiz emplea la palabra «incredulidad» para el abandono de la oración y los Compañeros no consideraban incredulidad el abandono de ninguna obra salvo la oración (Sunan Tirmidhi 2622); la otra opinión (la mayoría de los juristas: hanafíes, malikíes, shafiíes) es que comete un pecado gravísimo sin ser incrédulo. Para ambos, abandonar la oración es un crimen enorme." },
  "264": { mr: "कोणते कर्म अल्लाहला सर्वाधिक आवडते? उत्तर दिले: वेळेवर नमाज़ पढणे.",
           ar: "أي العمل أحب إلى الله؟ قال: الصلاة على وقتها.",
           fr: "Quelle œuvre Allah aime-t-Il le plus ? Il répondit : La prière accomplie à son heure.",
           es: "¿Qué obra es la más amada por Alá? Respondió: La oración hecha a su tiempo." },

