  "647": { mr: "व्यापारी माल (सध्याच्या विक्री किमतीनुसार)", ar: "عروض التجارة (بسعر البيع الحالي)", fr: "Marchandises (au prix de vente actuel)", es: "Mercancías (al precio de venta actual)" },
