Object.assign(window.ARKAN_X, {

  /* ── qaza o kafara ── */
  "507": { mr: "<span class=\"ic\">🔁</span>कदा आणि कफ्फारा", ar: "<span class=\"ic\">🔁</span>القضاء والكفارة", fr: "<span class=\"ic\">🔁</span>Le rattrapage et l'expiation", es: "<span class=\"ic\">🔁</span>La reposición y la expiación" },
  "508": { mr: "<b>कदा:</b> एखाद्या कारणाने सुटलेला रोजा नंतर राखणे. <b>कफ्फारा:</b> रमजानच्या दिवसात रोज्याच्या अवस्थेत जाणूनबुजून संभोग केल्यावर. खाण्या-पिण्याने रोजा तुटतो आणि त्याची कदा आवश्यक आहे.",
           ar: "<b>القضاء:</b> صيام يوم فات لعذر في وقت لاحق. <b>الكفارة:</b> تجب بالجماع عمدًا في نهار رمضان. والأكل والشرب يفسد الصوم وتلزمه القضاء فقط.",
           fr: "<b>Le rattrapage (qadâ') :</b> jeûner plus tard un jour manqué pour une excuse. <b>L'expiation (kaffâra) :</b> due en cas de rapport intime délibéré un jour de Ramadan. Manger ou boire rompt le jeûne et n'impose que le rattrapage.",
           es: "<b>La reposición (qada):</b> ayunar más tarde un día perdido por una excusa. <b>La expiación (kaffara):</b> se debe por relaciones íntimas deliberadas en un día de Ramadán. Comer o beber rompe el ayuno y solo obliga a reponerlo." },
  "509": { mr: "एका माणसाने रमजानमध्ये आपल्या बायकोशी संभोग केला. नबी ﷺ म्हणाले: गुलाम मुक्त कर; नसेल तर दोन महिने सलग रोजे ठेव; तेही शक्य नसेल तर साठ गरजवंतांना जेवू घाल.",
           ar: "أتى رجل امرأته في رمضان، فقال النبي ﷺ: أعتق رقبة؛ فإن لم تجد فصم شهرين متتابعين؛ فإن لم تستطع فأطعم ستين مسكينًا.",
           fr: "Un homme eut un rapport avec son épouse pendant Ramadan. Le Prophète ﷺ dit : affranchis un esclave ; si tu ne peux pas, jeûne deux mois consécutifs ; si tu ne peux pas, nourris soixante pauvres.",
           es: "Un hombre tuvo relaciones con su esposa en Ramadán. El Profeta ﷺ dijo: libera un esclavo; si no puedes, ayuna dos meses seguidos; si no puedes, alimenta a sesenta pobres." },
  "510": { mr: "<b>कफ्फाऱ्याचा क्रम:</b> गुलाम मुक्त करणे (आता शक्य नाही) ← साठ रोजे सलग ← साठ गरजवंतांना जेवू घालणे.",
           ar: "<b>ترتيب الكفارة:</b> عتق رقبة (وهو غير ممكن الآن) ← صيام ستين يومًا متتابعة ← إطعام ستين مسكينًا.",
           fr: "<b>L'ordre de l'expiation :</b> affranchir un esclave (impossible aujourd'hui) ← jeûner soixante jours consécutifs ← nourrir soixante pauvres.",
           es: "<b>El orden de la expiación:</b> liberar un esclavo (hoy no es posible) ← ayunar sesenta días seguidos ← alimentar a sesenta pobres." },
  "511": { mr: "कफ्फाऱ्याच्या रोज्यांमध्ये मधे एक दिवसही सुटला तर पुन्हा सुरुवातीपासून ठेवावे लागतात (स्त्रीसाठी हैद हे कारण अपवाद आहे).",
           ar: "إذا انقطع التتابع في صيام الكفارة ولو بيوم واحد استأنف من جديد (ويُستثنى عذر الحيض للمرأة).",
           fr: "Si la continuité des jeûnes d'expiation est interrompue, même un seul jour, il faut recommencer (les menstrues sont une exception pour la femme).",
           es: "Si se interrumpe la continuidad de los ayunos de expiación, aunque sea un día, hay que empezar de nuevo (la menstruación es una excepción para la mujer)." },
  "512": { mr: "कफ्फाऱ्यासोबत त्या दिवसाची कदाही ठेवावी लागते.", ar: "وتلزم مع الكفارة قضاء ذلك اليوم.", fr: "Avec l'expiation, il faut aussi rattraper ce jour.", es: "Con la expiación hay que reponer también ese día." },
  "513": { mr: "कदाचे रोजे रमजाननंतर कधीही ठेवता येतात, पण लवकर ठेवणे उत्तम. ⟦r⟧",
           ar: "تُقضى الأيام بعد رمضان في أي وقت، والأفضل المبادرة. ⟦r⟧",
           fr: "Les jours de rattrapage peuvent être jeûnés à tout moment après Ramadan, mais mieux vaut se hâter. ⟦r⟧",
           es: "Los días de reposición pueden ayunarse en cualquier momento tras Ramadán, pero es mejor apresurarse. ⟦r⟧" },
  "514": { mr: "⚠️ विनाकारण रमजानचा रोजा सोडणे हा मोठा गुन्हा आहे; तौबा आणि कदा दोन्ही आवश्यक आहेत.",
           ar: "⚠️ ترك صيام رمضان بغير عذر كبيرة؛ وتجب التوبة والقضاء.",
           fr: "⚠️ Abandonner le jeûne de Ramadan sans excuse est un grand péché ; le repentir et le rattrapage sont tous deux nécessaires.",
           es: "⚠️ Abandonar el ayuno de Ramadán sin excusa es un pecado grave; el arrepentimiento y la reposición son necesarios." },

  /* ── kisko rukhsat hai ── */
  "515": { mr: "<span class=\"ic\">🤝</span>कोणाला सवलत आहे", ar: "<span class=\"ic\">🤝</span>من له الرخصة", fr: "<span class=\"ic\">🤝</span>Qui bénéficie d'une dispense", es: "<span class=\"ic\">🤝</span>Quién tiene dispensa" },
  "516": { mr: "आणि जो आजारी असेल किंवा प्रवासात असेल तर इतर दिवसांत गणती पूर्ण करावी, आणि ज्यांना (म्हातारपणामुळे किंवा कायमच्या आजारामुळे) रोजा राखण्याची ताकद नाही त्यांच्यावर फिद्या आहे: एका गरजवंताचे अन्न.",
           ar: "ومن كان مريضًا أو على سفر فعدة من أيام أخر، وعلى الذين لا يطيقونه فدية طعام مسكين.",
           fr: "Quiconque est malade ou en voyage jeûnera un nombre équivalent d'autres jours ; ceux qui ne peuvent pas jeûner (vieillesse ou maladie chronique) ont une compensation : nourrir un pauvre.",
           es: "Quien esté enfermo o de viaje ayunará un número igual de otros días; quienes no puedan ayunar (vejez o enfermedad crónica) tienen una compensación: alimentar a un pobre." },
  "517": { mr: "अवस्था", ar: "الحال", fr: "Situation", es: "Situación" },
  "129": { mr: "हुकूम", ar: "الحكم", fr: "Statut", es: "Dictamen" },
  "518": { mr: "आजारी (ज्याच्या रोज्याने आजार वाढेल किंवा बरे होण्यास उशीर होईल)",
           ar: "المريض (الذي يزيد الصوم مرضه أو يؤخر شفاءه)",
           fr: "Le malade (dont le jeûne aggrave la maladie ou retarde la guérison)",
           es: "El enfermo (a quien el ayuno agrava la enfermedad o retrasa la curación)" },
  "519": { mr: "रोजा सोडावा, बरे झाल्यावर कदा", ar: "يفطر ويقضي بعد الشفاء", fr: "Qu'il rompe le jeûne et rattrape après la guérison", es: "Que rompa el ayuno y reponga tras curarse" },
  "520": { mr: "प्रवासी (शरई प्रवास)", ar: "المسافر (السفر الشرعي)", fr: "Le voyageur (voyage légal)", es: "El viajero (viaje legal)" },
  "521": { mr: "सवलत आहे, नंतर कदा; त्रास होत नसेल तर रोजा राखणे उत्तम",
           ar: "له الرخصة ويقضي بعدًا؛ فإن لم يشق عليه فالصيام أفضل",
           fr: "Il a une dispense et rattrape plus tard ; si cela ne lui est pas pénible, jeûner est meilleur",
           es: "Tiene dispensa y repone después; si no le resulta penoso, ayunar es mejor" },
  "522": { mr: "गर्भवती / स्तन्य देणारी (स्वतःच्या किंवा बाळाच्या जीवाच्या/आरोग्याच्या भीतीने)",
           ar: "الحامل والمرضع (خوفًا على نفسها أو على ولدها)",
           fr: "La femme enceinte ou allaitante (crainte pour elle-même ou pour son enfant)",
           es: "La embarazada o lactante (por temor a sí misma o a su hijo)" },
  "523": { mr: "रोजा सोडण्याची सवलत; नंतर कदा आवश्यक", ar: "لها الرخصة، وتلزمها القضاء بعدًا", fr: "Dispense de jeûner ; le rattrapage est ensuite nécessaire", es: "Dispensa de ayunar; después es necesaria la reposición" },
  "524": { mr: "म्हातारा किंवा कायमचा आजारी जो रोजा राखू शकत नाही",
           ar: "الشيخ الكبير أو المريض مرضًا مزمنًا الذي لا يستطيع الصيام",
           fr: "Le vieillard ou le malade chronique incapable de jeûner",
           es: "El anciano o enfermo crónico incapaz de ayunar" },
  "525": { mr: "प्रत्येक रोज्याबद्दल एका गरजवंताला अन्न (फिद्या)", ar: "فدية عن كل يوم: إطعام مسكين", fr: "Pour chaque jour : nourrir un pauvre (fidya)", es: "Por cada día: alimentar a un pobre (fidya)" },
  "526": { mr: "हैद व निफास असलेली स्त्री", ar: "الحائض والنفساء", fr: "La femme en menstrues ou en lochies", es: "La mujer con menstruación o puerperio" },
  "527": { mr: "रोजा ठेवू नये, नंतर कदा ठेवावी. नमाज़ची कदा नाही", ar: "تفطر وتقضي بعدًا، ولا تقضي الصلاة", fr: "Qu'elle ne jeûne pas et rattrape ensuite ; la prière n'est pas rattrapée", es: "Que no ayune y reponga después; la oración no se repone" },
  "528": { mr: "बालक / वेडा / कायम बेशुद्ध", ar: "الطفل / المجنون / فاقد الوعي دائمًا", fr: "L'enfant / le dément / l'inconscient permanent", es: "El niño / el demente / el inconsciente permanente" },
  "529": { mr: "फर्ज नाही", ar: "لا يجب", fr: "Non obligatoire", es: "No es obligatorio" },
  "530": { mr: "आम्हाला (हैदच्या रोज्यांची) कदा करण्याचा हुकूम दिला जात असे आणि नमाज़ची कदा करण्याचा हुकूम दिला जात नव्हता.",
           ar: "كنا نُؤمر بقضاء الصوم ولا نُؤمر بقضاء الصلاة.",
           fr: "On nous ordonnait de rattraper les jeûnes (des menstrues) et on ne nous ordonnait pas de rattraper les prières.",
           es: "Se nos ordenaba reponer los ayunos (de la menstruación) y no se nos ordenaba reponer las oraciones." },
  "531": { mr: "💡 फिद्या: प्रत्येक रोज्याबद्दल एका गरजवंताला पोटभर जेवण, किंवा तेवढे धान्य (एक मुद, सुमारे 750 ग्राम). ⟦r⟧",
           ar: "💡 الفدية: إطعام مسكين عن كل يوم، أو دفع مدٍّ من الطعام (نحو 750 جرامًا). ⟦r⟧",
           fr: "💡 La fidya : nourrir un pauvre pour chaque jour, ou donner cette quantité de nourriture (un mudd, environ 750 g). ⟦r⟧",
           es: "💡 La fidya: alimentar a un pobre por cada día, o dar esa cantidad de alimento (un mudd, unos 750 g). ⟦r⟧" },

  /* ── nafl roze ── */
  "532": { mr: "<span class=\"ic\">⭐</span>नफिल रोजे", ar: "<span class=\"ic\">⭐</span>صيام النفل", fr: "<span class=\"ic\">⭐</span>Les jeûnes surérogatoires", es: "<span class=\"ic\">⭐</span>Los ayunos voluntarios" },
  "533": { mr: "फजीलत", ar: "الفضل", fr: "Mérite", es: "Mérito" },
  "534": { mr: "संदर्भ", ar: "المرجع", fr: "Référence", es: "Referencia" },
  "535": { mr: "शव्वालचे ६ रोजे", ar: "ستة أيام من شوال", fr: "Les six jours de Chawwâl", es: "Los seis días de Shawal" },
  "536": { mr: "रमजाननंतर राखल्यास पूर्ण वर्षाच्या रोज्यांचे फळ", ar: "من صامها بعد رمضان فكأنما صام الدهر", fr: "Jeûnés après Ramadan, ils valent le jeûne de toute l'année", es: "Ayunados tras Ramadán, valen el ayuno de todo el año" },
  "537": { mr: "सहीह मुस्लिम ११६४", ar: "صحيح مسلم ١١٦٤", fr: "Sahih Muslim 1164", es: "Sahih Muslim 1164" },
  "538": { mr: "यवमे अरफा (९ जिल्हिज्जा) — बिगर हाजीसाठी", ar: "يوم عرفة (9 ذي الحجة) — لغير الحاج", fr: "Le jour d'Arafa (9 dhû al-hijja) — pour le non-pèlerin", es: "El día de Arafa (9 de du l-hiyya) — para quien no es peregrino" },
  "539": { mr: "मागील व पुढील वर्षाच्या (लहान) पापांचे प्रायश्चित्त", ar: "يكفّر سنة ماضية وسنة آتية (من الصغائر)", fr: "Expie les péchés (mineurs) de l'année passée et de l'année à venir", es: "Expía los pecados (menores) del año pasado y del siguiente" },
  "540": { mr: "सहीह मुस्लिम ११६२", ar: "صحيح مسلم ١١٦٢", fr: "Sahih Muslim 1162", es: "Sahih Muslim 1162" },
  "541": { mr: "यवमे आशूरा (१० मुहर्रम)", ar: "يوم عاشوراء (10 محرم)", fr: "Le jour d'Achoura (10 muharram)", es: "El día de Ashura (10 de Muharram)" },
  "542": { mr: "मागील एका वर्षाच्या पापांचे प्रायश्चित्त. सोबत ९ किंवा ११ तारखेचा रोजाही ठेवा",
           ar: "يكفّر سنة ماضية. ويُستحب صيام التاسع أو الحادي عشر معه",
           fr: "Expie les péchés de l'année passée. Jeûnez aussi le 9 ou le 11 avec lui",
           es: "Expía los pecados del año pasado. Ayuna también el 9 o el 11 junto con él" },
  "543": { mr: "मुहर्रमचे रोजे", ar: "صيام محرم", fr: "Les jeûnes de Muharram", es: "Los ayunos de Muharram" },
  "544": { mr: "रमजाननंतर सर्वात उत्तम रोजे", ar: "أفضل الصيام بعد رمضان", fr: "Les meilleurs jeûnes après Ramadan", es: "Los mejores ayunos después de Ramadán" },
  "545": { mr: "सहीह मुस्लिम ११६३", ar: "صحيح مسلم ١١٦٣", fr: "Sahih Muslim 1163", es: "Sahih Muslim 1163" },
  "546": { mr: "सोमवार व गुरुवार", ar: "الاثنين والخميس", fr: "Le lundi et le jeudi", es: "El lunes y el jueves" },
  "547": { mr: "या दिवशी कर्मे सादर केली जातात", ar: "تُعرض الأعمال فيهما", fr: "Les œuvres y sont présentées", es: "En esos días se presentan las obras" },
  "548": { mr: "सुनन तिर्मिझी ७४७", ar: "سنن الترمذي ٧٤٧", fr: "Sunan Tirmidhi 747", es: "Sunan Tirmidhi 747" },
  "549": { mr: "अय्यामे बीज (१३, १४, १५)", ar: "أيام البيض (13 و14 و15)", fr: "Les jours blancs (13, 14, 15)", es: "Los días blancos (13, 14, 15)" },
  "550": { mr: "दरमहा तीन रोजे", ar: "ثلاثة أيام من كل شهر", fr: "Trois jours chaque mois", es: "Tres días cada mes" },
  "551": { mr: "सहीह बुखारी १९७५", ar: "صحيح البخاري ١٩٧٥", fr: "Sahih Bukhari 1975", es: "Sahih Bujari 1975" },
  "552": { mr: "दाऊद (अ.स.) यांचा रोजा", ar: "صيام داود عليه السلام", fr: "Le jeûne de Dâwûd (paix sur lui)", es: "El ayuno de Dawud (la paz sea con él)" },
  "553": { mr: "एक दिवस रोजा, एक दिवस इफ्तार — सर्वात आवडता", ar: "يصوم يومًا ويفطر يومًا — وهو أحب الصيام", fr: "Un jour de jeûne, un jour de rupture — le plus aimé", es: "Un día de ayuno, un día sin ayuno — el más amado" },
  "554": { mr: "सहीह बुखारी ११३१", ar: "صحيح البخاري ١١٣١", fr: "Sahih Bukhari 1131", es: "Sahih Bujari 1131" },
  "555": { mr: "ज्याने रमजानचे रोजे राखले, नंतर शव्वालचे सहा रोजे राखले, तर जणू त्याने संपूर्ण काळाचे रोजे राखले.",
           ar: "من صام رمضان ثم أتبعه ستًّا من شوال كان كصيام الدهر.",
           fr: "Celui qui jeûne Ramadan puis y ajoute six jours de Chawwâl, c'est comme s'il avait jeûné toute une vie.",
           es: "Quien ayuna Ramadán y luego añade seis días de Shawal, es como si hubiera ayunado toda la vida." },
  "556": { mr: "⚠️ <b>रोजा राखण्यास मनाई:</b> ईद-उल-फित्र व ईद-उल-अजहाच्या दिवशी; आणि अय्यामे तशरीक (११–१३ जिल्हिज्जा) मध्येही (हाजीला कुर्बानी मिळत नसेल तर त्याच्यासाठी सवलत आहे). ⟦r⟧ ⟦r⟧",
           ar: "⚠️ <b>النهي عن الصيام:</b> يوم الفطر ويوم الأضحى؛ وأيام التشريق (11–13 ذي الحجة) أيضًا (ورخّص للحاج الذي لم يجد الهدي). ⟦r⟧ ⟦r⟧",
           fr: "⚠️ <b>Jeûnes interdits :</b> le jour de l'Aïd al-Fitr et de l'Aïd al-Adha ; ainsi que les jours de Tachrîq (11–13 dhû al-hijja) — avec une dispense pour le pèlerin qui n'a pas trouvé d'offrande. ⟦r⟧ ⟦r⟧",
           es: "⚠️ <b>Ayunos prohibidos:</b> el día del Id al-Fitr y del Id al-Adha; y también los días de Tashriq (11–13 de du l-hiyya) — con dispensa para el peregrino que no dispone de ofrenda. ⟦r⟧ ⟦r⟧" },
  "557": { mr: "⚠️ फक्त शुक्रवारचा दिवस निवडून रोजा राखणे (सोबत गुरुवार किंवा शनिवार न मिळवता) मकरूह आहे. ⟦r⟧",
           ar: "⚠️ يكره إفراد الجمعة بالصيام (بدون ضم الخميس أو السبت إليه). ⟦r⟧",
           fr: "⚠️ Jeûner uniquement le vendredi (sans y joindre le jeudi ou le samedi) est déconseillé. ⟦r⟧",
           es: "⚠️ Ayunar solo el viernes (sin añadir el jueves o el sábado) es desaconsejado. ⟦r⟧" },

  /* ── Lailatul-Qadr ── */
  "558": { mr: "<span class=\"ic\">✨</span>लैलतुल-कद्र", ar: "<span class=\"ic\">✨</span>ليلة القدر", fr: "<span class=\"ic\">✨</span>La nuit du Destin", es: "<span class=\"ic\">✨</span>La noche del Destino" },
  "559": { mr: "निःसंशय आम्ही हे (कुरआन) कद्रच्या रात्रीत अवतरित केले. आणि तू काय जाणतोस कद्रची रात काय आहे? कद्रची रात हजार महिन्यांपेक्षा उत्तम आहे.",
           ar: "إنا أنزلناه في ليلة القدر، وما أدراك ما ليلة القدر، ليلة القدر خير من ألف شهر.",
           fr: "Nous l'avons fait descendre la nuit du Destin. Et qui te fera savoir ce qu'est la nuit du Destin ? La nuit du Destin est meilleure que mille mois.",
           es: "Ciertamente lo hicimos descender en la noche del Destino. ¿Y qué te hará saber qué es la noche del Destino? La noche del Destino es mejor que mil meses." },
  "560": { mr: "कद्रची रात रमजानच्या शेवटच्या दशकातील विषम रात्रींमध्ये शोधा.",
           ar: "تحرّوا ليلة القدر في العشر الأواخر من رمضان في الليالي الوترية.",
           fr: "Cherchez la nuit du Destin dans les nuits impaires de la dernière décade de Ramadan.",
           es: "Buscad la noche del Destino en las noches impares de la última década de Ramadán." },
  "561": { mr: "जो कद्रच्या रात्रीत ईमान आणि फळाच्या अपेक्षेने उभा राहील (नमाज़ पढेल), त्याचे पूर्वीचे पाप माफ केले जातात.",
           ar: "من قام ليلة القدر إيمانًا واحتسابًا غُفر له ما تقدم من ذنبه.",
           fr: "Celui qui passe la nuit du Destin en prière, par foi et en espérant la récompense, ses péchés passés sont pardonnés.",
           es: "Quien pasa la noche del Destino en oración, con fe y esperando la recompensa, sus pecados anteriores le son perdonados." },
  "562": { mr: "दुआ", ar: "الدعاء", fr: "Invocation", es: "Súplica" },
  "563": { mr: "हे अल्लाह! तू माफ करणारा आहेस, माफी आवडते, म्हणून मला माफ कर.",
           ar: "اللهم إنك عفوٌّ تحب العفو فاعفُ عني.",
           fr: "Ô Allah ! Tu es Pardonneur et Tu aimes le pardon, alors pardonne-moi.",
           es: "¡Oh Alá! Tú eres Perdonador y amas el perdón, así que perdóname." },
  "564": { mr: "⟦r⟧⟦r⟧ — ही दुआ उम्मुल-मोमिनीन आयशा (र.अ.) यांच्या प्रश्नावर नबी ﷺ यांनी शिकवली.",
           ar: "⟦r⟧⟦r⟧ — علّمها النبي ﷺ لأم المؤمنين عائشة رضي الله عنها حين سألته.",
           fr: "⟦r⟧⟦r⟧ — le Prophète ﷺ l'a enseignée à Oumm al-Mou'minîn Aïcha (qu'Allah l'agrée) à sa demande.",
           es: "⟦r⟧⟦r⟧ — el Profeta ﷺ la enseñó a Umm al-Muminin Aisha (que Alá esté complacido con ella) a petición suya." },

  /* ── e'tikaf ── */
  "565": { mr: "<span class=\"ic\">🕌</span>एतेकाफ", ar: "<span class=\"ic\">🕌</span>الاعتكاف", fr: "<span class=\"ic\">🕌</span>L'i'tikâf", es: "<span class=\"ic\">🕌</span>El i'tikaf" },
  "566": { mr: "नबी ﷺ रमजानच्या शेवटच्या दशकाचा एतेकाफ करत असत, अगदी अल्लाहने त्यांना वफात दिली तोपर्यंत.",
           ar: "كان النبي ﷺ يعتكف العشر الأواخر من رمضان حتى توفاه الله.",
           fr: "Le Prophète ﷺ faisait la retraite des dix dernières nuits de Ramadan jusqu'à ce qu'Allah le rappelle.",
           es: "El Profeta ﷺ hacía el retiro de las diez últimas noches de Ramadán hasta que Alá lo llamó." },
  "567": { mr: "<b>व्याख्या:</b> अल्लाहच्या उपासनेच्या नियतीने मस्जिदीत राहणे.",
           ar: "<b>التعريف:</b> لزوم المسجد بنية عبادة الله.",
           fr: "<b>Définition :</b> demeurer à la mosquée avec l'intention d'adorer Allah.",
           es: "<b>Definición:</b> permanecer en la mezquita con la intención de adorar a Alá." },
  "568": { mr: "<b>रमजानच्या शेवटच्या दहा दिवसांचा एतेकाफ</b> — सुन्नत आहे, आणि नबी ﷺ यांचा हा कायमचा क्रम होता. सुरुवात २० रमजानला सूर्यास्तापूर्वी, समाप्ती ईदचा चंद्र पाहून.",
           ar: "<b>اعتكاف العشر الأواخر من رمضان</b> — سنة، وكان دأب النبي ﷺ. يبدأ قبل غروب ليلة 20 وينتهي برؤية هلال العيد.",
           fr: "<b>La retraite des dix derniers jours de Ramadan</b> — c'est une sunna et la pratique constante du Prophète ﷺ. Elle commence avant le coucher du soleil du 20 et se termine à la vision du croissant de l'Aïd.",
           es: "<b>El retiro de los diez últimos días de Ramadán</b> — es sunna y la práctica constante del Profeta ﷺ. Comienza antes de la puesta del sol del día 20 y termina con la visión del creciente del Id." },
  "569": { mr: "<b>नफिल एतेकाफ:</b> वर्षभर कधीही, थोड्या वेळासाठीही; मस्जिदीत प्रवेश करताना नियत करावी.",
           ar: "<b>الاعتكاف النفل:</b> في أي وقت من السنة، ولو لوقت قصير؛ وتكفي نية عند دخول المسجد.",
           fr: "<b>L'i'tikâf surérogatoire :</b> à tout moment de l'année, même pour peu de temps ; il suffit d'en former l'intention en entrant à la mosquée.",
           es: "<b>El i'tikaf voluntario:</b> en cualquier momento del año, aunque sea breve; basta intencionarlo al entrar en la mezquita." },
  "570": { mr: "<b>नवसाचा एतेकाफ</b> पूर्ण करणे आवश्यक आहे. ⟦r⟧", ar: "<b>اعتكاف النذر</b> يجب الوفاء به. ⟦r⟧", fr: "<b>L'i'tikâf voué (nadhr)</b> doit être accompli. ⟦r⟧", es: "<b>El i'tikaf prometido (nadr)</b> debe cumplirse. ⟦r⟧" },
  "571": { mr: "<b>स्त्रिया:</b> मस्जिदीत, शरई पर्दा आणि फितनेपासून सुरक्षिततेसह; पवित्र पत्नींनीही नबी ﷺ यांच्यानंतर एतेकाफ केला. ⟦r⟧",
           ar: "<b>النساء:</b> في المسجد مع الالتزام بالحجاب والعفة؛ وقد اعتكف أزواج النبي ﷺ بعده. ⟦r⟧",
           fr: "<b>Les femmes :</b> à la mosquée, avec le voile légal et à l'abri de la tentation ; les épouses du Prophète ﷺ ont fait la retraite après lui. ⟦r⟧",
           es: "<b>Las mujeres:</b> en la mezquita, con el velo legal y protegidas de la fitna; las esposas del Profeta ﷺ hicieron el retiro después de él. ⟦r⟧" },
  "572": { mr: "<b>एतेकाफ करणाऱ्याने</b> अत्यावश्यक गरज (शौचालय, फर्ज स्नान, वुजू) शिवाय बाहेर पडू नये आणि संभोग वर्ज्य आहे. ⟦r⟧",
           ar: "<b>والمعتكف</b> لا يخرج إلا لحاجة لازمة (الخلاء، الغسل الواجب، الوضوء)، ويُمنع الجماع. ⟦r⟧",
           fr: "<b>Le retraitant</b> ne sort que pour un besoin indispensable (toilettes, bain rituel obligatoire, ablutions), et le rapport intime est interdit. ⟦r⟧",
           es: "<b>El retirado</b> no sale sino por una necesidad imprescindible (aseo, baño ritual obligatorio, wudu), y las relaciones íntimas están prohibidas. ⟦r⟧" },
  "573": { mr: "💡 एतेकाफमध्ये कुरआन, झिक्र, दुआ, नवाफिल आणि तौबा-इस्तिगफारची काळजी घ्या; निरर्थक बोलणे आणि दुनियेच्या कामांपासून दूर राहा.",
           ar: "💡 في الاعتكاف اعتنِ بالقرآن والذكر والدعاء والنوافل والتوبة والاستغفار؛ وابتعد عن فضول الكلام وأشغال الدنيا.",
           fr: "💡 Pendant la retraite, consacrez-vous au Coran, au dhikr, à l'invocation, aux prières surérogatoires et au repentir ; évitez les conversations vaines et les affaires du bas monde.",
           es: "💡 Durante el retiro, dedícate al Corán, al dhikr, a la súplica, a las oraciones voluntarias y al arrepentimiento; evita las conversaciones vanas y los asuntos del mundo." },

  /* ── aadaab ── */
  "574": { mr: "<span class=\"ic\">🌿</span>रोज्याचे आदाब", ar: "<span class=\"ic\">🌿</span>آداب الصيام", fr: "<span class=\"ic\">🌿</span>Les convenances du jeûne", es: "<span class=\"ic\">🌿</span>Los modales del ayuno" },
  "575": { mr: "<b>सहरी खाणे</b> आणि ती शेवटच्या वेळेपर्यंत लांबवणे. ⟦r⟧", ar: "<b>تناول السحور</b> وتأخيره إلى آخر الوقت. ⟦r⟧", fr: "<b>Prendre le sahûr</b> et le retarder jusqu'à la fin de son temps. ⟦r⟧", es: "<b>Tomar el suhur</b> y retrasarlo hasta el final de su tiempo. ⟦r⟧" },
  "576": { mr: "<b>इफ्तार लवकर करणे.</b> ⟦r⟧", ar: "<b>تعجيل الفطر.</b> ⟦r⟧", fr: "<b>S'empresser de rompre le jeûne.</b> ⟦r⟧", es: "<b>Apresurar el iftar.</b> ⟦r⟧" },
  "577": { mr: "<b>जीभ, डोळे आणि कानांचे रक्षण</b> — निंदा, खोटे, शिवीगाळ आणि वाईट नजरेपासून दूर राहणे. ⟦r⟧",
           ar: "<b>حفظ اللسان والعين والأذن</b> — بالبعد عن الغيبة والكذب والسبّ والنظر المحرّم. ⟦r⟧",
           fr: "<b>Garder la langue, l'œil et l'oreille</b> — éviter la médisance, le mensonge, l'insulte et le regard interdit. ⟦r⟧",
           es: "<b>Cuidar la lengua, el ojo y el oído</b> — evitar la murmuración, la mentira, el insulto y la mirada ilícita. ⟦r⟧" },
  "578": { mr: "<b>कुरआनची तिलावत, तरावीह आणि तहज्जुद</b>ची काळजी घ्या. ⟦r⟧",
           ar: "<b>الاعتناء بتلاوة القرآن والتراويح والتهجد.</b> ⟦r⟧",
           fr: "<b>Récitation du Coran, tarâwîh et tahajjud</b> : à soigner. ⟦r⟧",
           es: "<b>Recitación del Corán, tarawih y tahayyud</b>: cuidarlos. ⟦r⟧" },
  "579": { mr: "<b>सदका व दान</b> — नबी ﷺ रमजानमध्ये सर्वात जास्त उदार होते. ⟦r⟧",
           ar: "<b>الصدقة والخير</b> — كان النبي ﷺ أجود الناس في رمضان. ⟦r⟧",
           fr: "<b>L'aumône et la charité</b> — le Prophète ﷺ était le plus généreux des hommes en Ramadan. ⟦r⟧",
           es: "<b>La limosna y la caridad</b> — el Profeta ﷺ era el más generoso en Ramadán. ⟦r⟧" },
  "580": { mr: "<b>सदका-ए-फित्र</b> ईदच्या नमाज़ेपूर्वी अदा करणे.", ar: "<b>صدقة الفطر</b> تُؤدَّى قبل صلاة العيد.", fr: "<b>La sadâqat al-fitr</b> : l'acquitter avant la prière de l'Aïd.", es: "<b>La sadaqat al-fitr</b>: entregarla antes de la oración del Id." },
  "581": { mr: "<b>एतेकाफ</b> — शेवटच्या दशकात.", ar: "<b>الاعتكاف</b> — في العشر الأواخر.", fr: "<b>L'i'tikâf</b> — durant la dernière décade.", es: "<b>El i'tikaf</b> — en la última década." },
  "582": { mr: "<b>दुआ</b> — रोजादाराची दुआ स्वीकारली जाते.", ar: "<b>الدعاء</b> — دعوة الصائم لا تُرد.", fr: "<b>L'invocation</b> — celle du jeûneur est exaucée.", es: "<b>La súplica</b> — la del ayunante es aceptada." },

  /* ── pichla / agla ── */
  "583": { mr: "→ जकात", ar: "→ الزكاة", fr: "→ La zakât", es: "→ La zakat" },
  "584": { mr: "हज व उमरा ←", ar: "الحج والعمرة ←", fr: "Hajj et Umrah ←", es: "Hach y Umra ←" }
});



